package main

import (
	"bytes"
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, errors.New("count must be greater than 0")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &out

	err := cmd.Run()
	output := out.String()

	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w, output: %s", err, output)
	}

	if runtime.GOOS == "windows" {
		// Example Windows summary: Minimum = 10ms, Maximum = 12ms, Average = 11ms
		re := regexp.MustCompile(`Average = (\d+)ms`)
		matches := re.FindStringSubmatch(output)
		if len(matches) < 2 {
			return 0, errors.New("could not parse average latency from windows ping output")
		}
		val, parseErr := strconv.ParseFloat(matches[1], 64)
		if parseErr != nil {
			return 0, fmt.Errorf("failed to parse latency: %w", parseErr)
		}
		return val, nil
	}

	// Unix-like (Linux, macOS, FreeBSD)
	// Example Linux summary: rtt min/avg/max/mdev = 0.045/0.045/0.045/0.000 ms
	// Example macOS summary: round-trip min/avg/max/stddev = 23.456/23.456/23.456/0.000 ms
	re := regexp.MustCompile(`(?:rtt|round-trip) min/avg/max/[a-z-]+ = [^/]+/([^/]+)/`)
	matches := re.FindStringSubmatch(output)
	if len(matches) < 2 {
		return 0, errors.New("could not parse average latency from unix ping output")
	}
	val, parseErr := strconv.ParseFloat(matches[1], 64)
	if parseErr != nil {
		return 0, fmt.Errorf("failed to parse latency: %w", parseErr)
	}
	return val, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avgLatency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
