package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

var (
	// Regex to match Unix/Linux/macOS ping summary line
	// Example: rtt min/avg/max/mdev = 0.045/0.045/0.045/0.000 ms
	// Example: round-trip min/avg/max/std-dev = 14.588/14.588/14.588/0.000 ms
	reSummaryUnix = regexp.MustCompile(`=\s*[\d.]+/([\d.]+)(?:/[\d.]+)*\s*ms`)

	// Regex to match Windows ping summary line
	// Example: Minimum = 14ms, Maximum = 14ms, Average = 14ms
	reSummaryWin = regexp.MustCompile(`Average\s*=\s*([\d.]+)\s*ms`)

	// Regex to match individual ping reply lines as a fallback
	// Example: time=14.5 ms | time<1ms | time=14ms
	reLine = regexp.MustCompile(`time[=<](\d+(?:\.\d+)?)\s*ms`)
)

// MeasureLatency pings a specified host a user-defined number of times 
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()
	outputStr := string(out)

	// Attempt to parse Unix/Linux/macOS summary
	if matches := reSummaryUnix.FindStringSubmatch(outputStr); len(matches) > 1 {
		if val, parseErr := strconv.ParseFloat(matches[1], 64); parseErr == nil {
			return val, nil
		}
	}

	// Attempt to parse Windows summary
	if matches := reSummaryWin.FindStringSubmatch(outputStr); len(matches) > 1 {
		if val, parseErr := strconv.ParseFloat(matches[1], 64); parseErr == nil {
			return val, nil
		}
	}

	// Fallback: parse individual lines
	var total float64
	var countSuccess int
	for _, match := range reLine.FindAllStringSubmatch(outputStr, -1) {
		if val, parseErr := strconv.ParseFloat(match[1], 64); parseErr == nil {
			total += val
			countSuccess++
		}
	}

	if countSuccess > 0 {
		return total / float64(countSuccess), nil
	}

	// If no latency could be parsed, return the underlying command error if present
	if err != nil {
		return 0, fmt.Errorf("ping failed: %v, output: %s", err, outputStr)
	}

	return 0, fmt.Errorf("could not parse ping output: %s", outputStr)
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	latency, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", host, latency)
}

