package main

import (
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()
	outputStr := string(out)

	avg, parseErr := parseAvg(outputStr)
	if parseErr == nil {
		return avg, nil
	}

	if err != nil {
		return 0, fmt.Errorf("ping command failed: %v, output: %s", err, outputStr)
	}

	return 0, parseErr
}

// parseAvg extracts the average latency from the ping command output.
// It supports standard output formats from Linux, macOS, and Windows.
func parseAvg(output string) (float64, error) {
	// Unix-like systems (Linux, macOS, BSD)
	// Examples:
	// rtt min/avg/max/mdev = 0.044/0.044/0.044/0.000 ms
	// round-trip min/avg/max/stddev = 14.233/14.233/14.233/0.000 ms
	// round-trip min/avg/max = 14.233/14.233/14.233 ms
	reUnix := regexp.MustCompile(`(?i)(?:rtt|round-trip) min/avg/max(?:/(?:mdev|stddev|std-dev))? = [\d.]+/([\d.]+)/`)
	if matches := reUnix.FindStringSubmatch(output); len(matches) > 1 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// Windows
	// Example: Average = 4ms
	reWin := regexp.MustCompile(`(?i)Average\s*=\s*([\d.]+)\s*ms`)
	if matches := reWin.FindStringSubmatch(output); len(matches) > 1 {
		return strconv.ParseFloat(matches[1], 64)
	}

	return 0, fmt.Errorf("could not parse average latency from ping output")
}

func main() {
	host := "google.com"
	count := 4

	fmt.Printf("Measuring latency to %s (%d attempts)...\n", host, count)

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency: %.2f ms\n", avg)
}

