package main

import (
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, errors.New("count must be greater than 0")
	}
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}

	var cmd *exec.Cmd
	// Adjust ping command flags based on the operating system
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		// Linux, macOS, and other Unix-like systems
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()

	// Regex to extract time from ping output
	// Matches "time=12.3 ms" (Linux/macOS) and "time=12ms" (Windows)
	re := regexp.MustCompile(`time=(\d+\.?\d*)\s*ms`)
	matches := re.FindAllStringSubmatch(string(out), -1)

	if len(matches) == 0 {
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(out))
		}
		return 0, errors.New("no valid ping responses found in output (100% packet loss or unresolvable host)")
	}

	var total float64
	validCount := 0
	for _, match := range matches {
		val, parseErr := strconv.ParseFloat(match[1], 64)
		if parseErr == nil {
			total += val
			validCount++
		}
	}

	if validCount == 0 {
		return 0, errors.New("failed to parse latency values from ping output")
	}

	// Calculate and return the average
	return total / float64(validCount), nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Measuring latency to %s (%d attempts)...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.3f ms\n", avg)
}

