package main

import (
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, errors.New("count must be greater than 0")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()
	output := string(out)

	avg, parseErr := parseAverage(output)
	if parseErr != nil {
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %v, output: %s", err, output)
		}
		return 0, fmt.Errorf("failed to parse ping output: %v", parseErr)
	}

	return avg, nil
}

// parseAverage attempts to extract the average latency from the ping command output.
// It supports Linux, macOS, and Windows summary formats, with a fallback to individual packet lines.
func parseAverage(output string) (float64, error) {
	// Try Unix summary (Linux/macOS)
	// Example: rtt min/avg/max/mdev = 0.043/0.043/0.043/0.000 ms
	// Example: round-trip min/avg/max/stddev = 12.345/12.345/12.345/0.000 ms
	reUnix := regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max/[a-z]+\s*=\s*[0-9.]+/([0-9.]+)/`)
	if m := reUnix.FindStringSubmatch(output); len(m) > 1 {
		return strconv.ParseFloat(m[1], 64)
	}

	// Try Windows summary
	// Example: Average = 12ms
	reWin := regexp.MustCompile(`Average\s*=\s*([0-9.]+)ms`)
	if m := reWin.FindStringSubmatch(output); len(m) > 1 {
		return strconv.ParseFloat(m[1], 64)
	}

	// Fallback: parse individual lines 
	// This handles cases where the summary is missing (e.g., Windows with count=1)
	// Example: time=14.2 ms (Linux/macOS) or time=14ms / time<1ms (Windows)
	reInd := regexp.MustCompile(`(?i)time[=<]\s*([0-9.]+)\s*ms`)
	matches := reInd.FindAllStringSubmatch(output, -1)
	if len(matches) > 0 {
		var sum float64
		validCount := 0
		for _, m := range matches {
			val, err := strconv.ParseFloat(m[1], 64)
			if err == nil {
				sum += val
				validCount++
			}
		}
		if validCount > 0 {
			return sum / float64(validCount), nil
		}
	}

	return 0, errors.New("could not extract latency from ping output")
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

