package main

import (
	"bytes"
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
	"strings"
)

// pingTimeRegex matches the time output from standard ping commands across different OSes.
// It handles variations like "time=12.3 ms", "time<1ms", and locale-specific decimal commas "time=12,3 ms".
var pingTimeRegex = regexp.MustCompile(`time[=<](\d+(?:[.,]\d+)?)\s*ms`)

// MeasureLatency pings a specified host a user-defined number of times 
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &out

	// We ignore the immediate error returned by Run() because partial packet loss 
	// results in a non-zero exit code but still provides valid latency data to parse.
	_ = cmd.Run()

	matches := pingTimeRegex.FindAllStringSubmatch(out.String(), -1)
	if len(matches) == 0 {
		return 0, fmt.Errorf("no successful pings recorded for host %s (host may be unreachable or invalid)", host)
	}

	var total float64
	validPings := 0
	for _, match := range matches {
		// Normalize locale-specific decimal commas to dots for parsing
		valStr := strings.Replace(match[1], ",", ".", 1)
		val, err := strconv.ParseFloat(valStr, 64)
		if err == nil {
			total += val
			validPings++
		}
	}

	if validPings == 0 {
		return 0, fmt.Errorf("failed to parse latency values from ping output")
	}

	avg := total / float64(validPings)
	return avg, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s over %d attempts: %.2f ms\n", host, count, avg)
}

