package main

import (
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

var (
	// Regex for Linux/macOS ping summary lines
	// e.g., "rtt min/avg/max/mdev = 10.123/11.456/12.789/1.234 ms"
	// e.g., "round-trip min/avg/max/stddev = 10.123/11.456/12.789/1.234 ms"
	unixSummaryRe = regexp.MustCompile(`(?:rtt|round-trip) min/avg/max/(?:mdev|stddev|pipe) = [\d\.]+/([\d\.]+)/[\d\.]+/[\d\.]+ ms`)

	// Regex for Windows English ping summary line
	// e.g., "Average = 11ms"
	winSummaryRe = regexp.MustCompile(`Average = ([\d\.]+)ms`)

	// Fallback regex for individual ping reply lines across different OSes
	// e.g., "time=12.3 ms", "time=12ms", "time<1ms"
	fallbackRe = regexp.MustCompile(`time[=<]([\d\.]+)\s*ms`)
)

// MeasureLatency pings a specified host a user-defined number of times 
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
		// Force C locale on Unix-like systems to ensure consistent English output for parsing
		cmd.Env = append(os.Environ(), "LC_ALL=C")
	}

	out, err := cmd.CombinedOutput()
	outputStr := string(out)

	// 1. Try parsing the Unix summary line
	if matches := unixSummaryRe.FindStringSubmatch(outputStr); len(matches) > 1 {
		if avg, parseErr := strconv.ParseFloat(matches[1], 64); parseErr == nil {
			return avg, nil
		}
	}

	// 2. Try parsing the Windows summary line
	if matches := winSummaryRe.FindStringSubmatch(outputStr); len(matches) > 1 {
		if avg, parseErr := strconv.ParseFloat(matches[1], 64); parseErr == nil {
			return avg, nil
		}
	}

	// 3. Fallback: parse individual reply lines and calculate average manually
	// This helps bypass localized summary lines on Windows or partial packet loss scenarios
	allMatches := fallbackRe.FindAllStringSubmatch(outputStr, -1)
	if len(allMatches) > 0 {
		var sum float64
		var validCount int
		for _, m := range allMatches {
			if val, parseErr := strconv.ParseFloat(m[1], 64); parseErr == nil {
				sum += val
				validCount++
			}
		}
		if validCount > 0 {
			return sum / float64(validCount), nil
		}
	}

	// If we reach here, we couldn't parse any latency data
	if err != nil {
		return 0, fmt.Errorf("ping failed and output could not be parsed: %w\nOutput: %s", err, outputStr)
	}
	return 0, fmt.Errorf("could not parse average latency from ping output:\n%s", outputStr)
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency: %.2f ms\n", avg)
}

