package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()
	output := string(out)

	// Regex for Unix-like systems (Linux, macOS)
	// Matches lines like: rtt min/avg/max/mdev = 0.045/0.045/0.045/0.000 ms
	// or: round-trip min/avg/max/stddev = 14.541/14.541/14.541/0.000 ms
	reUnix := regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max/(?:mdev|stddev|std-dev)\s+=\s+[\d\.,]+/([\d\.,]+)/[\d\.,]+/[\d\.,]+\s+ms`)
	if matches := reUnix.FindStringSubmatch(output); len(matches) > 1 {
		// Replace comma with dot to handle locales that use comma as decimal separator
		avgStr := strings.Replace(matches[1], ",", ".", 1)
		val, parseErr := strconv.ParseFloat(avgStr, 64)
		if parseErr == nil {
			return val, nil
		}
	}

	// Regex for Windows systems
	// Matches lines like: Minimum = 10ms, Maximum = 10ms, Average = 10ms
	reWin := regexp.MustCompile(`(?i)Average\s*[=:]\s*<?(\d+)\s*ms`)
	if matches := reWin.FindStringSubmatch(output); len(matches) > 1 {
		val, parseErr := strconv.ParseFloat(matches[1], 64)
		if parseErr == nil {
			return val, nil
		}
	}

	// If parsing failed and the command also returned an error, return the command error
	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w, output: %s", err, output)
	}

	return 0, fmt.Errorf("could not parse average latency from ping output")
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Measuring latency to %s (%d attempts)...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.2f ms\n", avg)
}

