// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if strings.TrimSpace(host) == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	// Adjust ping command flags based on the operating system
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()
	outputStr := string(out)

	// Regex to match individual ping times (e.g., time=14.2 ms or time<1ms)
	// Parsing individual lines is more resilient across different OS summary formats and locales.
	re := regexp.MustCompile(`(?i)time\s*[=<]\s*([\d\.]+)\s*ms`)
	matches := re.FindAllStringSubmatch(outputStr, -1)

	if len(matches) == 0 {
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %v, output: %s", err, outputStr)
		}
		return 0, fmt.Errorf("no successful pings found in output")
	}

	var total float64
	validCount := 0
	for _, match := range matches {
		val, parseErr := strconv.ParseFloat(match[1], 64)
		if parseErr == nil {
			total += val
			validCount++
		}
	}

	if validCount == 0 {
		return 0, fmt.Errorf("failed to parse any latency values from output")
	}

	avg := total / float64(validCount)
	return avg, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error measuring latency: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.3f ms\n", avg)
