// pingTimeRegex matches the time output from standard ping commands across different OS and locales.
// It handles "time=12.3 ms", "time<1ms", and locale-specific decimal separators like "time=12,3 ms".
var pingTimeRegex = regexp.MustCompile(`time[=<](\d+(?:[.,]\d+)?)\s*ms`)

// MeasureLatency executes the system ping command and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}

	var cmd *exec.Cmd
	// Adjust ping command flags based on the operating system
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()

	// Parse all matching time values from the output
	matches := pingTimeRegex.FindAllStringSubmatch(string(out), -1)

	if len(matches) == 0 {
		if err != nil {
			return 0, fmt.Errorf("ping failed: %v, output: %s", err, string(out))
		}
		return 0, fmt.Errorf("no successful pings found in output")
	}

	var sum float64
	var validCount int

	for _, match := range matches {
		// Replace comma with dot to handle European locale decimal separators
		valStr := strings.Replace(match[1], ",", ".", 1)
		val, parseErr := strconv.ParseFloat(valStr, 64)
		if parseErr == nil {
			sum += val
			validCount++
		}
	}

	if validCount == 0 {
		return 0, fmt.Errorf("failed to parse latency values from ping output")
	}

	return sum / float64(validCount), nil
}

func main() {
	host := flag.String("host", "8.8.8.8", "Target host to ping (e.g., google.com or 127.0.0.1)")
	count := flag.Int("count", 4, "Number of ping attempts")
	flag.Parse()

	fmt.Printf("Pinging %s %d times...\n", *host, *count)

	avg, err := MeasureLatency(*host, *count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", *host, avg)
}

