package main

import (
	"bytes"
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, errors.New("count must be greater than 0")
	}
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}

	var cmd *exec.Cmd
	// Adjust ping command flags based on the operating system
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &out

	// We intentionally ignore the error from Run() because the ping command 
	// returns a non-zero exit code on packet loss or unreachable hosts. 
	// We still want to parse any successful replies from the output.
	_ = cmd.Run()

	// Regex to extract latency from standard ping output formats.
	// Matches "time=14.5 ms", "time=14ms", or "time<1ms" (Windows fast reply).
	// Using (?i) for case-insensitivity to handle minor OS/locale variations.
	re := regexp.MustCompile(`(?i)time[=<]([\d.,]+)\s*ms`)
	matches := re.FindAllStringSubmatch(out.String(), -1)

	if len(matches) == 0 {
		return 0, fmt.Errorf("no successful pings or unable to parse latency for host %s", host)
	}

	var total float64
	var successCount int
	for _, match := range matches {
		// Replace comma with dot to handle locales that use comma as decimal separator
		valStr := strings.Replace(match[1], ",", ".", 1)
		val, err := strconv.ParseFloat(valStr, 64)
		if err == nil {
			total += val
			successCount++
		}
	}

	if successCount == 0 {
		return 0, fmt.Errorf("failed to parse valid latency values for host %s", host)
	}

	return total / float64(successCount), nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Measuring latency to %s (%d attempts)...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.2f ms\n", avg)
}

