package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	output, err := cmd.CombinedOutput()
	outStr := string(output)

	// Regex patterns for different OS ping outputs to extract the average latency
	regexes := []*regexp.Regexp{
		regexp.MustCompile(`rtt min/avg/max/mdev = [\d\.]+/([\d\.]+)/`),           // Linux
		regexp.MustCompile(`round-trip min/avg/max/stddev = [\d\.]+/([\d\.]+)/`),  // macOS / FreeBSD
		regexp.MustCompile(`round-trip min/avg/max = [\d\.]+/([\d\.]+)/`),         // BusyBox / Alpine Linux
		regexp.MustCompile(`Average = ([\d\.]+)ms`),                               // Windows (English)
	}

	for _, re := range regexes {
		if matches := re.FindStringSubmatch(outStr); len(matches) > 1 {
			avg, parseErr := strconv.ParseFloat(matches[1], 64)
			if parseErr == nil {
				return avg, nil
			}
		}
	}

	if err != nil {
		return 0, fmt.Errorf("ping command failed: %w, output: %s", err, outStr)
	}

	return 0, fmt.Errorf("unable to parse average latency from ping output")
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.2f ms\n", avg)
}

