import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a user-defined number of times 
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	// Adjust ping command flags based on the operating system
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		// Linux, macOS, and other Unix-like systems
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()

	// Regex to extract latency values from standard ping outputs across different OSes.
	// Matches patterns like "time=12.3 ms", "time=12ms", or "time<1ms"
	re := regexp.MustCompile(`(?i)time[=<](\d+(?:\.\d+)?)\s*ms`)
	matches := re.FindAllStringSubmatch(string(out), -1)

	if len(matches) == 0 {
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %v, output: %s", err, string(out))
		}
		return 0, fmt.Errorf("no latency data found in ping output")
	}

	var sum float64
	validCount := 0
	for _, match := range matches {
		val, parseErr := strconv.ParseFloat(match[1], 64)
		if parseErr == nil {
			sum += val
			validCount++
		}
	}

	if validCount == 0 {
		return 0, fmt.Errorf("failed to parse latency values from ping output")
	}

	avg := sum / float64(validCount)
	return avg, nil
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Measuring latency to %s (%d attempts)...\n", host, count)

	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.2f ms\n", avg)
}

