// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	var out bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &out

	err := cmd.Run()
	output := out.String()

	if output == "" && err != nil {
		return 0, fmt.Errorf("ping failed: %w", err)
	}

	if runtime.GOOS == "windows" {
		// Windows summary typically looks like:
		// Minimum = 14ms, Maximum = 14ms, Average = 14ms
		// We match ` = Xms` to avoid matching `time=Xms` from individual packets.
		re := regexp.MustCompile(`\s=\s*(\d+)\s*ms`)
		matches := re.FindAllStringSubmatch(output, -1)
		if len(matches) > 0 {
			lastMatch := matches[len(matches)-1]
			val, parseErr := strconv.ParseFloat(lastMatch[1], 64)
			if parseErr == nil {
				return val, nil
			}
		}
	} else {
		// Unix-like (Linux, macOS, etc.) summary typically looks like:
		// rtt min/avg/max/mdev = 14.123/14.456/14.789/0.123 ms
		// round-trip min/avg/max/stddev = 14.123/14.456/14.789/0.123 ms
		// round-trip min/avg/max = 14.123/14.456/14.789 ms (Busybox)
		re := regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max(?:/[a-z-]+)?\s*=\s*[\d.]+/([\d.]+)(?:/[\d.]+)?(?:/[\d.]+)?\s*ms`)
		matches := re.FindStringSubmatch(output)
		if len(matches) > 1 {
			val, parseErr := strconv.ParseFloat(matches[1], 64)
			if parseErr == nil {
				return val, nil
			}
		}
	}

	if err != nil {
		return 0, fmt.Errorf("ping failed: %w", err)
	}
	return 0, fmt.Errorf("could not parse average latency from ping output")
}

func main() {
	host := "google.com"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

