package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
	"strings"
)

// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if strings.HasPrefix(host, "-") {
		return 0, fmt.Errorf("invalid host: must not start with '-'")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()
	output := string(out)

	// 1. Try to parse individual packet times (works for most standard English outputs)
	reInd := regexp.MustCompile(`(?i)time[=<]\s*(\d+(?:\.\d+)?)\s*ms`)
	matches := reInd.FindAllStringSubmatch(output, -1)
	if len(matches) > 0 {
		var sum float64
		for _, m := range matches {
			val, _ := strconv.ParseFloat(m[1], 64)
			sum += val
		}
		return sum / float64(len(matches)), nil
	}

	// 2. Fallback: Try Unix/macOS summary line
	// Example: rtt min/avg/max/mdev = 0.045/0.045/0.045/0.000 ms
	// Example: round-trip min/avg/max/stddev = 14.005/14.005/14.005/0.000 ms
	reUnix := regexp.MustCompile(`(?i)(?:rtt|round-trip)\s+min\/avg\/max\/[a-z]+\s*=\s*[\d.]+\/([\d.]+)\/[\d.]+\/[\d.]+\s*ms`)
	if m := reUnix.FindStringSubmatch(output); m != nil {
		val, parseErr := strconv.ParseFloat(m[1], 64)
		if parseErr == nil {
			return val, nil
		}
	}

	// 3. Fallback: Try Windows summary line
	// Example: Average = 14ms
	reWin := regexp.MustCompile(`(?i)Average\s*=\s*(\d+(?:\.\d+)?)\s*ms`)
	if m := reWin.FindStringSubmatch(output); m != nil {
		val, parseErr := strconv.ParseFloat(m[1], 64)
		if parseErr == nil {
			return val, nil
		}
	}

	// If we reach here, we couldn't parse the latency
	if err != nil {
		return 0, fmt.Errorf("ping failed: %w, output: %s", err, strings.TrimSpace(output))
	}
	return 0, fmt.Errorf("could not parse latency from ping output")
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

