package main

import (
	"flag"
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// pingTimeRegex matches the time output from standard ping commands across different OSes.
// Examples: "time=14.2 ms" (Linux), "time=14.234 ms" (macOS), "time=14ms" or "time<1ms" (Windows)
var pingTimeRegex = regexp.MustCompile(`(?i)time[=<](\d+(?:\.\d+)?)\s*ms`)

// MeasureLatency pings a specified host a user-defined number of times 
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, fmt.Errorf("host cannot be empty")
	}
	if count <= 0 {
		return 0, fmt.Errorf("count must be greater than 0")
	}

	var cmd *exec.Cmd
	// Adjust the ping command flag based on the operating system
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		// Linux, macOS, and other Unix-like systems
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	// Execute the command and capture combined output (stdout + stderr)
	out, err := cmd.CombinedOutput()

	// Parse the output for individual ping response times
	matches := pingTimeRegex.FindAllStringSubmatch(string(out), -1)

	if len(matches) == 0 {
		if err != nil {
			return 0, fmt.Errorf("ping command failed: %v\nOutput: %s", err, string(out))
		}
		return 0, fmt.Errorf("no latency data could be parsed from ping output")
	}

	// Calculate the average latency from the successfully parsed responses
	var total float64
	for _, match := range matches {
		val, parseErr := strconv.ParseFloat(match[1], 64)
		if parseErr == nil {
			total += val
		}
	}

	if total == 0 && len(matches) > 0 {
	    // Fallback in case regex matched but parsing failed unexpectedly
	    return 0, fmt.Errorf("failed to calculate average latency")
	}

	return total / float64(len(matches)), nil
}

func main() {
	host := flag.String("host", "8.8.8.8", "Target host or IP address to ping")
	count := flag.Int("count", 4, "Number of ping attempts")
	flag.Parse()

	fmt.Printf("Pinging %s %d times...\n", *host, *count)

	avg, err := MeasureLatency(*host, *count)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error measuring latency: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", *host, avg)
}

