fix.generatedCode:
package main

import (
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings the specified host the given number of times and returns the average latency in milliseconds.
// It uses the system 'ping' command via os/exec and parses the output to extract the average RTT.
func MeasureLatency(host string, count int) (float64, error) {
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}
	if count <= 0 {
		return 0, errors.New("count must be positive")
	}

	// Use exec.Command directly to avoid shell injection vulnerabilities
	// and handle cross-platform differences for the ping command.
	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	output, err := cmd.CombinedOutput()
	if err != nil {
		return 0, fmt.Errorf("failed to execute ping: %w (output: %s)", err, string(output))
	}

	outputStr := string(output)
	var avgStr string

	if runtime.GOOS == "windows" {
		// Windows ping output typically contains: "Average = 14ms"
		re := regexp.MustCompile(`(?i)average\s*=\s*([\d.]+)\s*ms`)
		matches := re.FindStringSubmatch(outputStr)
		if len(matches) >= 2 {
			avgStr = matches[1]
		}
	} else {
		// Unix-like (Linux, macOS) ping output typically contains:
		// Linux: "rtt min/avg/max/mdev = 12.345/23.456/34.567/5.678 ms"
		// macOS: "round-trip min/avg/max/stddev = 12.345/23.456/34.567/5.678 ms"
		re := regexp.MustCompile(`(?:rtt|round-trip)\s+min/avg/max(?:/[a-z-]+)?\s*=\s*[\d.]+/([\d.]+)/[\d.]+(?:/[\d.]+)?\s*ms`)
		matches := re.FindStringSubmatch(outputStr)
		if len(matches) >= 2 {
			avgStr = matches[1]
		}
	}

	if avgStr == "" {
		return 0, errors.New("could not find or parse RTT statistics in ping output")
	}

	avg, err := strconv.ParseFloat(avgStr, 64)
	if err != nil {
		return 0, fmt.Errorf("failed to convert average latency to float: %w", err)
	}

	return avg, nil
}

