package main

import (
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a user-defined number of times
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, fmt.Errorf("ping count must be greater than 0")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	// Force C locale to ensure consistent output formatting (e.g., using dots 
	// instead of commas for decimal separators on Unix-like systems).
	cmd.Env = append(cmd.Environ(), "LC_ALL=C", "LANG=C")

	// We use CombinedOutput to capture both stdout and stderr.
	// We ignore the error returned by CombinedOutput because ping may
	// return a non-zero exit code if some packets are lost, but we might
	// still be able to parse the average latency from the partial output.
	out, _ := cmd.CombinedOutput()
	outputStr := string(out)

	// Regex for Unix-like systems (Linux, macOS)
	// Examples:
	// Linux: rtt min/avg/max/mdev = 0.041/0.041/0.041/0.000 ms
	// macOS: round-trip min/avg/max/stddev = 20.104/20.104/20.104/0.000 ms
	reUnix := regexp.MustCompile(`(?:rtt|round-trip) min/avg/max/[a-z-]+ = [0-9.]+/([0-9.]+)/[0-9.]+/[0-9.]+ ms`)
	if matches := reUnix.FindStringSubmatch(outputStr); len(matches) > 1 {
		if avg, err := strconv.ParseFloat(matches[1], 64); err == nil {
			return avg, nil
		}
	}

	// Regex for Windows (English locale)
	// Example: Minimum = 14ms, Maximum = 14ms, Average = 14ms
	reWin := regexp.MustCompile(`Average = ([0-9.]+)ms`)
	if matches := reWin.FindStringSubmatch(outputStr); len(matches) > 1 {
		if avg, err := strconv.ParseFloat(matches[1], 64); err == nil {
			return avg, nil
		}
	}

	return 0, fmt.Errorf("failed to parse ping output or host is unreachable:\n%s", outputStr)
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency: %.3f ms\n", avg)
}

