package main

import (
	"errors"
	"fmt"
	"os/exec"
	"regexp"
	"runtime"
	"strconv"
)

// MeasureLatency pings a specified host a user-defined number of times 
// and returns the average latency in milliseconds.
func MeasureLatency(host string, count int) (float64, error) {
	if count <= 0 {
		return 0, errors.New("count must be greater than 0")
	}
	if host == "" {
		return 0, errors.New("host cannot be empty")
	}

	var cmd *exec.Cmd
	if runtime.GOOS == "windows" {
		cmd = exec.Command("ping", "-n", strconv.Itoa(count), host)
	} else {
		cmd = exec.Command("ping", "-c", strconv.Itoa(count), host)
	}

	out, err := cmd.CombinedOutput()
	if err != nil && len(out) == 0 {
		return 0, fmt.Errorf("ping command failed: %w", err)
	}

	outputStr := string(out)

	// Try Unix-like summary (Linux/macOS)
	// Example: rtt min/avg/max/mdev = 0.045/0.045/0.045/0.000 ms
	reUnix := regexp.MustCompile(`=\s*[\d.]+/([\d.]+)/[\d.]+/[\d.]+\s*ms`)
	if matches := reUnix.FindStringSubmatch(outputStr); len(matches) > 1 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// Try Windows summary (English)
	// Example: Average = 4ms
	reWin := regexp.MustCompile(`Average\s*=\s*([\d.]+)\s*ms`)
	if matches := reWin.FindStringSubmatch(outputStr); len(matches) > 1 {
		return strconv.ParseFloat(matches[1], 64)
	}

	// Fallback: parse individual ping replies and calculate average manually
	// This helps with localized Windows versions (e.g., matching "time=14ms" or "time<1ms")
	reIndividual := regexp.MustCompile(`time[=<](\d+\.?\d*)\s*ms`)
	if matches := reIndividual.FindAllStringSubmatch(outputStr, -1); len(matches) > 0 {
		var sum float64
		validCount := 0
		for _, m := range matches {
			val, parseErr := strconv.ParseFloat(m[1], 64)
			if parseErr == nil {
				sum += val
				validCount++
			}
		}
		if validCount > 0 {
			return sum / float64(validCount), nil
		}
	}

	return 0, fmt.Errorf("could not parse average latency from ping output")
}

func main() {
	host := "8.8.8.8"
	count := 4

	fmt.Printf("Pinging %s %d times...\n", host, count)
	avg, err := MeasureLatency(host, count)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Average latency to %s: %.2f ms\n", host, avg)
}

